// src/routes/users/[id].server.ts (server only, never in the client bundle)
import type { LoaderContext } from '@pyreon/router'
import { getUser } from '../../lib/users'

export async function serverLoader({ params }: LoaderContext) {
  return getUser(params.id!)
}

// src/routes/users/[id].tsx
import { useLoaderData } from '@pyreon/router'

export const renderMode = 'isr' // stale-while-revalidate, 60 s by default

export default function UserPage() {
  const user = useLoaderData<{ name: string }>()
  return <h1>{user.name}</h1>
}
